export type SyncHead = {
  generation: number
  device_name: string
  created_at: string
}

export type SyncOutcome = 'synced' | 'up_to_date' | 'degraded' | 'failed'

/**  The phase of the current or last cycle. */
export type SyncPhase =
  | 'idle'
  | 'scanning'
  | 'fetching'
  | 'planning'
  | 'downloading'
  | 'snapshotting'
  | 'applying'
  | 'uploading'
  | 'committing'
  | 'confirming'
  | 'finalizing'

export type SyncProgress = {
  done: number
  total: number
}

/**  The full sync status, published as `SyncStatusChanged`. */
export type SyncStatus = SyncStatus_Serialize | SyncStatus_Deserialize

/**  Full sync status, revisioned so a delayed read cannot replace a newer value. */
export type SyncStatusChanged =
  SyncStatusChanged_Serialize | SyncStatusChanged_Deserialize

/**  Full sync status, revisioned so a delayed read cannot replace a newer value. */
export type SyncStatusChanged_Deserialize = SyncStatus_Deserialize

/**  Full sync status, revisioned so a delayed read cannot replace a newer value. */
export type SyncStatusChanged_Serialize = SyncStatus_Serialize

/**  The full sync status, published as `SyncStatusChanged`. */
export type SyncStatus_Deserialize = {
  /**  Increases with every change, so a delayed read cannot replace a newer value. */
  revision: number
  availability: SyncAvailability
  phase: SyncPhase
  progress?: SyncProgress | null
  last_success_at?: number | null
  last_result?: SyncOutcome | null
  last_error?: SyncError | null
  open_conflicts: number
  blocked_items: BlockedItem[]
  head?: SyncHead | null
  /**  The last cycle merged a diverged remote branch. */
  diverged?: boolean
}

/**  The full sync status, published as `SyncStatusChanged`. */
export type SyncStatus_Serialize = {
  /**  Increases with every change, so a delayed read cannot replace a newer value. */
  revision: number
  availability: SyncAvailability
  phase: SyncPhase
  progress: SyncProgress | null
  last_success_at: number | null
  last_result: SyncOutcome | null
  last_error: SyncError | null
  open_conflicts: number
  blocked_items: BlockedItem[]
  head: SyncHead | null
  /**  The last cycle merged a diverged remote branch. */
  diverged: boolean
}

export type TrafficRate = {
  download: number
  upload: number
}

export type UpdateSource = 'nyanpasu' | 'github' | 'ghfast' | 'sourceforge'

/**  Message for inter-window communication */
export type WindowMessageEvent = {
  /**  Source window label */
  from: string
  /**  Target window label (use "*" for broadcast) */
  to: string
  /**  Message type/event name */
  event: string
  /**  Message payload */
  payload: any
}

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null]
  ? () => Promise<void>
  : (payload: T) => Promise<void>

type EventEmitTo<T> = [T] extends [null]
  ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void>
  : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>

function makeEvent<TListen, TEmit = TListen>(
  name: string,
  serialize?: (payload: TEmit) => unknown,
  deserialize?: (payload: any) => TListen,
) {
  const mapEvent =
    (cb: __TAURI_EVENT.EventCallback<TListen>) =>
    (event: __TAURI_EVENT.Event<any>) =>
      cb({
        ...event,
        payload: deserialize ? deserialize(event.payload) : event.payload,
      })
  const mapPayload = (payload: TEmit) =>
    serialize ? serialize(payload) : payload

  const base = {
    listen: (cb: __TAURI_EVENT.EventCallback<TListen>) =>
      __TAURI_EVENT.listen(name, mapEvent(cb)),
    once: (cb: __TAURI_EVENT.EventCallback<TListen>) =>
      __TAURI_EVENT.once(name, mapEvent(cb)),
    emit: ((payload: TEmit) =>
      __TAURI_EVENT.emit(
        name,
        mapPayload(payload),
      ) as unknown) as EventEmit<TEmit>,
    emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) =>
      __TAURI_EVENT.emitTo(
        to,
        name,
        mapPayload(payload),
      ) as unknown) as EventEmitTo<TEmit>,
  }

  const fn = (
    target:
      | import('@tauri-apps/api/webview').Webview
      | import('@tauri-apps/api/window').Window,
  ) => ({
    listen: (cb: __TAURI_EVENT.EventCallback<TListen>) =>
      target.listen(name, mapEvent(cb)),
    once: (cb: __TAURI_EVENT.EventCallback<TListen>) =>
      target.once(name, mapEvent(cb)),
    emit: ((payload: TEmit) =>
      target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
    emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) =>
      target.emitTo(
        to,
        name,
        mapPayload(payload),
      ) as unknown) as EventEmitTo<TEmit>,
  })

  return Object.assign(fn, base)
}
